{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "segments" not in case or "budget" not in case:
        raise ValueError("case requires segments and budget")

    segments = case["segments"]
    budget = case["budget"]
    if not isinstance(segments, list):
        raise ValueError("segments must be a list")
    if isinstance(budget, bool) or not isinstance(budget, int) or budget < 0:
        raise ValueError("budget must be a nonnegative integer")

    names = set()
    validated = []
    for index, segment in enumerate(segments):
        if not isinstance(segment, dict):
            raise ValueError("each segment must be an object")
        required = ("name", "importance", "minimum", "capacity")
        if any(field not in segment for field in required):
            raise ValueError("segment requires name, importance, minimum, and capacity")

        name = segment["name"]
        importance = segment["importance"]
        minimum = segment["minimum"]
        capacity = segment["capacity"]

        if not isinstance(name, str) or not name:
            raise ValueError("segment name must be a nonempty string")
        if name in names:
            raise ValueError("segment names must be unique")
        names.add(name)
        if isinstance(importance, bool) or not isinstance(importance, int) or importance < 0:
            raise ValueError("importance must be a nonnegative integer")
        if isinstance(minimum, bool) or not isinstance(minimum, int) or minimum < 0:
            raise ValueError("minimum must be a nonnegative integer")
        if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity < minimum:
            raise ValueError("capacity must be an integer at least equal to minimum")

        validated.append((index, name, importance, minimum, capacity))

    quota_sum = sum(segment[3] for segment in validated)
    capacity_sum = sum(segment[4] for segment in validated)
    if budget < quota_sum or budget > capacity_sum:
        raise ValueError("budget is infeasible")

    allocated = [segment[3] for segment in validated]
    remaining = budget - quota_sum
    while remaining:
        best = None
        for index, _name, importance, _minimum, capacity in validated:
            if allocated[index] >= capacity:
                continue
            if best is None:
                best = index
                continue
            best_importance = validated[best][2]
            if importance * (allocated[best] + 1) > best_importance * (allocated[index] + 1):
                best = index
        if best is None:
            raise ValueError("budget cannot be allocated")
        allocated[best] += 1
        remaining -= 1

    allocations = [
        {"name": segment[1], "allocated": allocated[segment[0]]}
        for segment in validated
    ]
    allocation_by_name = {
        decision["name"]: decision["allocated"] for decision in allocations
    }
    total_allocated = sum(decision["allocated"] for decision in allocations)
    return {
        "allocations": allocations,
        "allocation_by_name": allocation_by_name,
        "total_allocated": total_allocated,
    }
